<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Contact Us · EBay</title><?php echo app('Illuminate\Foundation\Vite')(['resources/css/app.css','resources/js/app.js']); ?></head><body><main class="public-contact"><section class="contact-hero"><div class="contact-brand"><i class="bi bi-bag-heart-fill"></i> EBay</div><p class="eyebrow">We are here to help</p><h1>Contact us</h1><p>Questions about products, delivery, or an existing order? Reach us using any convenient channel.</p></section><section class="contact-grid"><?php if($contact->phone): ?><a class="contact-card" href="tel:<?php echo e(preg_replace('/\s+/', '', $contact->phone)); ?>"><i class="bi bi-telephone"></i><div><small>Phone</small><strong><?php echo e($contact->phone); ?></strong></div></a><?php endif; ?> <?php if($contact->whatsapp): ?><a class="contact-card" href="https://wa.me/<?php echo e(preg_replace('/\D+/', '', $contact->whatsapp)); ?>" target="_blank"><i class="bi bi-whatsapp"></i><div><small>WhatsApp</small><strong><?php echo e($contact->whatsapp); ?></strong></div></a><?php endif; ?> <?php if($contact->messenger_url): ?><a class="contact-card" href="<?php echo e($contact->messenger_url); ?>" target="_blank"><i class="bi bi-messenger"></i><div><small>Messenger</small><strong>Chat with us</strong></div></a><?php endif; ?> <?php if($contact->email): ?><a class="contact-card" href="mailto:<?php echo e($contact->email); ?>"><i class="bi bi-envelope"></i><div><small>Email</small><strong><?php echo e($contact->email); ?></strong></div></a><?php endif; ?> <?php if($contact->address): ?><div class="contact-card"><i class="bi bi-geo-alt"></i><div><small>Address</small><strong><?php echo nl2br(e($contact->address)); ?></strong></div></div><?php endif; ?> <?php if($contact->business_hours): ?><div class="contact-card"><i class="bi bi-clock"></i><div><small>Business hours</small><strong><?php echo e($contact->business_hours); ?></strong></div></div><?php endif; ?> <?php if(!$contact->phone && !$contact->whatsapp && !$contact->messenger_url && !$contact->email && !$contact->address): ?><div class="contact-empty">Contact information will be available soon.</div><?php endif; ?></section></main></body></html>
